// -----------------------------------------------------------------------------
// matched_filter.v  -  Hermes sonar pulse-compression FIR (transposed form)
//
// y[n] = sum_{k=0}^{N-1} h[k] * x[n-k]
// h[] = time-reversed transmit chirp, loaded from a hex file generated by
// sim/export_vectors.py. Transposed form keeps the critical path to one
// multiply + one add, independent of N.
//
// This is the reference (fully parallel) version used to verify bit-exactness
// against the Python model. A folded / multiplier-shared version for the
// low-power FPGA build is planned (see rtl/README.md).
// -----------------------------------------------------------------------------
`timescale 1ns/1ps

module matched_filter #(
    parameter N         = 128,              // number of taps
    parameter DW        = 12,               // input sample width (signed)
    parameter CW        = 12,               // coefficient width (signed)
    parameter AW        = 32,               // accumulator / output width
    parameter COEF_FILE = "vectors/coeffs.hex"
) (
    input  wire                 clk,
    input  wire                 rst,        // synchronous, active high
    input  wire                 in_valid,
    input  wire signed [DW-1:0] x,
    output reg                  out_valid,
    output reg  signed [AW-1:0] y
);

    reg signed [CW-1:0] h [0:N-1];
    reg signed [AW-1:0] z [0:N-2];          // transposed-form delay line

    initial $readmemh(COEF_FILE, h);

    // sign-extend the input once so every product is computed at AW bits
    wire signed [AW-1:0] xe = {{(AW-DW){x[DW-1]}}, x};

    integer i;
    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < N-1; i = i + 1) z[i] <= {AW{1'b0}};
            y         <= {AW{1'b0}};
            out_valid <= 1'b0;
        end else begin
            out_valid <= in_valid;
            if (in_valid) begin
                y <= h[0] * xe + z[0];
                for (i = 0; i < N-2; i = i + 1)
                    z[i] <= h[i+1] * xe + z[i+1];
                z[N-2] <= h[N-1] * xe;
            end
        end
    end

endmodule
